import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("Claim Office - quote base premiums and fee", () => {
  it.todo("empty item list -> premium 5 G (only the processing fee)");
  it.todo("single sword -> base 100 + fee 5, with first insurance 10% surcharge = 115 G");
  it.todo("single amulet -> base 60 + first insurance 6 + fee 5 = 71 G");
  it.todo("single staff -> base 80 + first insurance 8 + fee 5 = 93 G");
  it.todo("single potion -> base 40 + first insurance 4 + fee 5 = 49 G");
});

describe("Claim Office - component building blocks", () => {
  it.todo("2 runes -> 50 G base premium");
  it.todo("3 runes -> 60 G base premium (block applies)");
  it.todo("4 runes -> 100 G base premium (no block - block requires exactly 3)");
  it.todo("7 runes -> 175 G base premium");
  it.todo("2 runes + 1 moonstone -> 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones -> 120 G base premium (two separate blocks)");
});

describe("Claim Office - individual premium modifiers", () => {
  it.todo("cursed sword adds 50% risk surcharge (50 G of base)");
  it.todo("highly enchanted sword (enchantment >= 5) adds 30% risk surcharge");
  it.todo("sword with exactly enchantment 5 -> high-enchantment surcharge applies");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge");
  it.todo("long-standing customer (>= 2 years) receives 20% loyalty discount");
  it.todo("customer with exactly 2 years -> loyalty discount applies");
});

describe("Claim Office - modifier scope on multi-item policies", () => {
  it.todo("cursed sword + plain amulet -> policy base 160, curse adds 50 (of cursed item), = 210 before fee");
});

describe("Claim Office - integration examples", () => {
  it.todo("newcomer with cursed sword (steel, ench 3) -> premium 165 G");
  it.todo("long-standing customer's second contract, cursed sword (steel ench 7) -> premium 160 G");
});

describe("Claim Office - rounding in MHPCO's favor", () => {
  it.todo("premium yielding 197.5 G -> final premium 198 G (rounded up)");
  it.todo("payout yielding 350.5 G -> final payout 350 G (rounded down)");
});

describe("Claim Office - claim processing basic", () => {
  it.todo("regular sword (steel, ench 3), damage 500 -> payout 400 (minus 100 deductible)");
  it.todo("damage to a rune (value 250), damage 200 -> payout 100 (minus deductible)");
});

describe("Claim Office - claim special clauses", () => {
  it.todo("dragon-material sword, ench 5, damage 800 -> payout 700 (dragon full reimbursement, then deductible)");
  it.todo("steel sword, ench 9, damage 1000 -> payout 400 (high-enchantment 50% then deductible)");
  it.todo("dragon-material sword, ench 9, damage 1000 -> payout 400 (50% rule wins, then deductible)");
  it.todo("dragon-material sword, ench 8, damage 1000 -> payout 400 (high-enchantment applies, then deductible)");
});

describe("Claim Office - deductible per damage event", () => {
  it.todo("dragon attack damages sword (500) and amulet (300) -> payout 600 (deductible once per item)");
});

describe("Claim Office - cap", () => {
  it.todo("cap based on unmodified insurance value: cursed sword -> cap 2000");
  it.todo("sword insured, two successive 1500 claims -> first payout 1400 remaining 600, second payout 600 remaining 0");
  it.todo("policy covers two swords -> insurance sum 2000, cap 4000; both swords damaged separately");
});

describe("Claim Office - error handling", () => {
  it.todo("quote with unknown item type -> throws / non-zero exit");
  it.todo("claim references item not in policy -> throws / non-zero exit");
  it.todo("claim with more damages of a type than covered -> throws / non-zero exit");
  it.todo("claim with negative damage amount -> throws / non-zero exit");
});

