export const runScenario = (scenario: Scenario): ScenarioResult => {
  const results: Result[] = scenario.steps.map((step) => {
    const quote = step as QuoteStep;
    let premium = 0;
    for (const item of quote.items) {
      let base = 0;
      if (item.type === "sword") base = 100;
      premium += base;
      premium += base * 0.1; // first insurance surcharge
    }
    premium += 5; // processing fee
    return { premium };
  });
  return { results };
};

