const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
};
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const PROCESSING_FEE = 5;

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const results: Result[] = scenario.steps.map((step) => {
    const quote = step as QuoteStep;
    let premium = 0;
    for (const item of quote.items) {
      const base = BASE_PREMIUM_BY_ITEM_TYPE[item.type] ?? 0;
      premium += base;
      premium += base * FIRST_INSURANCE_SURCHARGE_RATE;
    }
    premium += PROCESSING_FEE;
    return { premium };
  });

