const quotePremium = (
  items: Item[],
  customer: Customer,
  isFollowUpContract: boolean,
): number => {
  const itemsPremium = items.reduce(
    (total, item) => total + itemPremium(item),
    0,
  );
  const policyBase = items.reduce((total, item) => total + baseFor(item), 0);
  const loyaltyDiscount = surcharge(
    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
    policyBase,
    LOYALTY_DISCOUNT_RATE,
  );
  const followUpDiscount = surcharge(
    isFollowUpContract,
    policyBase,
    FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
  );
  return itemsPremium - loyaltyDiscount - followUpDiscount + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  let quoteCount = 0;
  const results: Result[] = scenario.steps.map((step) => {
    const quote = step as QuoteStep;
    const isFollowUpContract = quoteCount > 0;
    quoteCount += 1;
    return {
      premium: quotePremium(quote.items, scenario.customer, isFollowUpContract),
    };
  });
  return { results };
};

