const quotePremium = (
  items: Item[],
  customer: Customer,
  isFollowUpContract: boolean,
): number => {
  const mainItems = items.filter((item) => item.type in BASE_PREMIUM_BY_ITEM_TYPE);
  const components = items.filter(
    (item) => !(item.type in BASE_PREMIUM_BY_ITEM_TYPE),
  );

  const { itemsPremium: mainPremium, policyBase: mainBase } = mainItems.reduce(
    (totals, item) => ({
      itemsPremium: totals.itemsPremium + itemPremium(item),
      policyBase: totals.policyBase + baseFor(item),
    }),
    { itemsPremium: 0, policyBase: 0 },
  );

  const componentBase = basePremium(components);
  const componentPremium =
    componentBase + componentBase * FIRST_INSURANCE_SURCHARGE_RATE;

  const itemsPremium = mainPremium + componentPremium;
  const policyBase = mainBase + componentBase;

  const loyaltyDiscount = proportionalAmount(
    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
    policyBase,
    LOYALTY_DISCOUNT_RATE,
  );
  const followUpDiscount = proportionalAmount(
    isFollowUpContract,
    policyBase,
    FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
  );
  const premium =
    itemsPremium - loyaltyDiscount - followUpDiscount + PROCESSING_FEE;
  return Math.ceil(premium);
};

