export const runScenario = (scenario: Scenario): ScenarioResult => {
  const policies: { insuranceSum: number }[] = [];
  const results: Result[] = scenario.steps.map((step, index) => {
    if (step.op === "claim") {
      const policy = policies[step.policy];
      const cap = policy.insuranceSum * CAP_MULTIPLIER;
      const payout = step.incident.damages.reduce((total, damage) => {
        return total + (damage.amount - DEDUCTIBLE_PER_DAMAGE);
      }, 0);
      return { payout, remainingCap: cap - payout };
    }
    const isFollowUpContract = index > 0;
    policies[index] = {
      insuranceSum: step.items.reduce(
        (total, item) => total + (INSURANCE_VALUE_BY_ITEM_TYPE[item.type] ?? 0),
        0,
      ),
    };
    return {
      premium: quotePremium(step.items, scenario.customer, isFollowUpContract),
    };
  });
  return { results };
};

